sp_widget.client_script:
api.controller = function () {
    /* No client behaviour needed - the CTA is a plain link. */
    var c = this
}

sp_widget.css:
// Colours come from theme variables only - no raw hex values.
.x-car-complaint-cta {
    .x-car-cta-title {
        font-size: 1.25rem;
        margin: 0 0 0.5rem;
        color: $text-color;
    }

    .x-car-cta-text {
        color: $text-muted;
        margin-bottom: 1rem;
    }

    .btn-lg {
        min-height: 2.75rem;
    }
}

sp_widget.script:
;(function () {
    data.catalogItemPage = 'sc_cat_item'
    data.producer = null

    // Resolve the "File a Complaint" record producer for the complaint table at
    // run time instead of hardcoding a catalog item sys_id.
    var producer = new GlideRecord('sc_cat_item_producer')
    producer.addQuery('table_name', 'x_2203703_car_re_0_complaint')
    producer.addQuery('active', true)
    producer.orderBy('name')
    producer.setLimit(1)
    producer.query()

    if (producer.next()) {
        data.producer = {
            sys_id: producer.getUniqueValue(),
            name: producer.getDisplayValue('name'),
            short_description: producer.getDisplayValue('short_description'),
        }
    }
})()
